class Solution:
    def treeModes(self, root: Optional[TreeNode]) -> List[int]:
        count = Counter()
        stack = [root] if root else []
        while stack:
            node = stack.pop()
            count[node.val] += 1
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        top = max(count.values())
        return [v for v, c in count.items() if c == top]

