function treeModes(root: TreeNode | null): number[] {
  let modes: number[] = [];
  let prev: number | null = null, streak = 0, best = 0;
  const stack: TreeNode[] = [];
  let node = root;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop()!;
    streak = node.val === prev ? streak + 1 : 1;
    prev = node.val;
    if (streak > best) { best = streak; modes = [node.val]; }
    else if (streak === best) modes.push(node.val);
    node = node.right;
  }
  return modes;
}

